package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.lang.reflect.*;
import java.nio.*;
import java.util.*;

/** Numerical directional derivatives from optimizer changes, frozen recurrence and full wire recovery. */
public final class R26NeuralDiagnosticsTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static Field member(String name)throws Exception{Field f=NeuralFamilyR26.class.getDeclaredField(name);f.setAccessible(true);return f;}
    static double[] vector(NeuralFamilyR26 model,String name)throws Exception{return (double[])member(name).get(model);}
    static int[] draw(Random random){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int q=random.nextInt(i+1),v=d[q];d[q]=d[i];d[i]=v;}return d;}
    static byte[] save(NeuralFamilyR26 model)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();model.write(new DataOutputStream(bytes));return bytes.toByteArray();}
    static NeuralFamilyR26 restore(String family,int variant,byte[] bytes)throws IOException{NeuralFamilyR26 m=new NeuralFamilyR26(family,variant);m.read(new DataInputStream(new ByteArrayInputStream(bytes)));return m;}
    static byte[] legacy(byte[] bytes){check(ByteBuffer.wrap(bytes).getInt()==0x26220003,"Not a v3 checkpoint");byte[] old=Arrays.copyOf(bytes,bytes.length-9);ByteBuffer.wrap(old).putInt(0x26220002);return old;}
    static void freezeInputFrom(NeuralFamilyR26 probe,NeuralFamilyR26 source)throws Exception{member("t").setLong(probe,member("t").getLong(source));int[][] a=(int[][])member("ring").get(probe),b=(int[][])member("ring").get(source);for(int i=0;i<a.length;i++)System.arraycopy(b[i],0,a[i],0,10);System.arraycopy(vector(source,"recurrent"),0,vector(probe,"recurrent"),0,40);}
    public static void main(String[] args)throws Exception{
        double maxDerivativeError=0;int graphs=0;
        for(String family:new String[]{"F03","F04","F05","F06","F07"})for(int variant=0;variant<3;variant++){
            graphs++;Random random=new Random(260703+variant);NeuralFamilyR26 model=new NeuralFamilyR26(family,variant);for(int i=0;i<12;i++)model.update(draw(random));byte[] prior=save(model);int[] target=draw(random);double[] oldWeights=vector(model,"weights").clone(),oldMomentum=vector(model,"momentum").clone();double before=model.objective(target);check(Arrays.equals(prior,save(model)),"Objective mutated persistent state");model.update(target);TrainingDiagnosticsR26.Step step=model.lastTrainingStep();check(step.update==13&&model.completedTrainingUpdates()==13,"Full lifetime counter");check(Math.abs(before-step.lossBefore)<1e-10,"Before loss differs");
            NeuralFamilyR26 fixed=restore(family,variant,save(model)),original=restore(family,variant,prior);freezeInputFrom(fixed,original);check(Math.abs(fixed.objective(target)-step.lossAfter)<1e-10,"After loss consumed updated raw/recurrent context");
            double[] actualWeights=vector(model,"weights"),actualMomentum=vector(model,"momentum"),rawGradient=new double[oldWeights.length];double delta=0,norm=0,scale=step.gradientNorm>5?5/step.gradientNorm:1;for(int i=0;i<oldWeights.length;i++){double change=actualWeights[i]-oldWeights[i];delta+=change*change;rawGradient[i]=(actualMomentum[i]-.9*oldMomentum[i])/(.1*scale);norm+=rawGradient[i]*rawGradient[i];}check(Math.abs(Math.sqrt(delta)-step.parameterDeltaNorm)<1e-12,"Measured full weight delta");check(Math.abs(Math.sqrt(norm)-step.gradientNorm)<1e-9,"Raw gradient norm and actual optimizer change disagree");
            double[] parameters=vector(original,"weights");for(int trial=0;trial<8;trial++){
                double eps=1e-4,projection=0;double[] direction=new double[parameters.length];for(int i=0;i<direction.length;i++){direction[i]=(random.nextBoolean()?1:-1)/64.0;projection+=rawGradient[i]*direction[i];parameters[i]=oldWeights[i]+eps*direction[i];}double plus=original.objective(target);for(int i=0;i<direction.length;i++)parameters[i]=oldWeights[i]-eps*direction[i];double minus=original.objective(target);System.arraycopy(oldWeights,0,parameters,0,parameters.length);double error=Math.abs((plus-minus)/(2*eps)-projection);maxDerivativeError=Math.max(maxDerivativeError,error);check(error<2e-5,"Numerical directional derivative differs: "+family+"/"+variant+" "+error);
            }
            check(Arrays.equals(prior,save(original)),"Finite differences mutated original state");original.update(draw(random));check(step.inputHash.equals(original.lastTrainingStep().inputHash),"Input hash observed target");byte[] complete=save(model);NeuralFamilyR26 copy=restore(family,variant,complete);check(copy.lastTrainingStep()==null,"Restore invented a new measurement");int[] next=draw(random);model.update(next);copy.update(next);check(Arrays.equals(save(model),save(copy)),"Complete next update differs");
            long updates=model.completedTrainingUpdates();model.resetTemporalContext();check(model.completedTrainingUpdates()==updates&&model.lastTrainingStep()==null,"Gap reset learned lifetime or stale measurement");NeuralFamilyR26 gapCopy=restore(family,variant,save(model));check(gapCopy.completedTrainingUpdates()==updates&&gapCopy.optimizerProtocol().endsWith("KNOWN_LIFETIME"),"v3 counter provenance missing");next=draw(random);model.update(next);gapCopy.update(next);check(Arrays.equals(save(model),save(gapCopy)),"Gap checkpoint/next update differs");
            byte[] source=save(model);byte[] old=legacy(source);NeuralFamilyR26 migrated=restore(family,variant,old);check(migrated.optimizerProtocol().endsWith("LEGACY_COUNTER_LOWER_BOUND")&&migrated.completedTrainingUpdates()==member("t").getLong(model),"Old checkpoint fabricated unknown lifetime");check(Arrays.equals(old,legacy(save(migrated))),"Old numeric checkpoint projection changed on migration");next=draw(random);model.update(next);migrated.update(next);check(Arrays.equals(legacy(save(model)),legacy(save(migrated))),"Old numeric execution changed on v2 import");
            byte[] unchanged=save(model),bad=unchanged.clone();Arrays.fill(bad,bad.length-9,bad.length-1,(byte)0xff);try{model.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("Negative lifetime accepted");}catch(IOException expected){}check(Arrays.equals(unchanged,save(model)),"Bad counter damaged prior model");bad=unchanged.clone();bad[bad.length-1]=2;try{model.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("Unknown counter flag accepted");}catch(IOException expected){}check(Arrays.equals(unchanged,save(model)),"Bad provenance damaged prior model");
            if(variant==0){boolean canceled=false;for(int operations:new int[]{1,100,1000,10000,100000}){model.read(new DataInputStream(new ByteArrayInputStream(unchanged)));ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,operations,()->false));try{model.update(target);}catch(BudgetTokenSU1.Yield expected){canceled=true;check(Arrays.equals(unchanged,save(model))&&model.lastTrainingStep()==null,"Interrupted update changed weights/momentum/recurrence/counter");}finally{ExecutionBudgetR26.leave();}}check(canceled,"No cooperative inference was interrupted");}
            if(args.length>0&&variant==0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0],family+"-state-sample.bin"),save(model));
        }
        System.out.println("R26_NEURAL_DIAGNOSTICS_PASS|graphs="+graphs+"|directionalChecks=120|maxDirectionalDerivativeError="+maxDerivativeError+"|fixedPreLabelRingAndRecurrence=true|actualOptimizerAndFullWeightDelta=true|restoreNextGapCancelAtomic=true|v2UnknownCounterExplicit=true|scope=SYNTHETIC_KERNEL_NOT_NATURAL_QUALITY");
    }
}
